class Solution:
    def countQuadruplets(self, nums: List[int]) -> int:
        ans = 0
        pair = Counter()
        for c in range(len(nums)):
            for d in range(c + 1, len(nums)):
                ans += pair[nums[d] - nums[c]]
            for a in range(c):
                pair[nums[a] + nums[c]] += 1
        return ans

