        unordered_map<int, int> pair;
        for (int c = 0; c < n; c++) {
            for (int d = c + 1; d < n; d++)
                ans += pair[nums[d] - nums[c]];
            for (int a = 0; a < c; a++)
                pair[nums[a] + nums[c]]++;
        }
        return ans;
    }
};

