class Solution {
    public int countQuadruplets(int[] nums) {
        int n = nums.length, ans = 0;
        Map<Integer, Integer> pair = new HashMap<>();
        for (int c = 0; c < n; c++) {
            for (int d = c + 1; d < n; d++)
                ans += pair.getOrDefault(nums[d] - nums[c], 0);
            for (int a = 0; a < c; a++)
                pair.merge(nums[a] + nums[c], 1, Integer::sum);
        }
        return ans;
    }
}

