var countQuadruplets = function(nums) {
    const n = nums.length;
    let ans = 0;
    const pair = new Map();
    for (let c = 0; c < n; c++) {
        for (let d = c + 1; d < n; d++)
            ans += pair.get(nums[d] - nums[c]) || 0;
        for (let a = 0; a < c; a++) {
            const s = nums[a] + nums[c];
            pair.set(s, (pair.get(s) || 0) + 1);
        }
    }
    return ans;
};
